const steuerung = {
  driveId: 'b!C2yhEx592Ei36yvay6U9n2886_vvW61LokJwBCKhlW_uiHYCBMlCRaEn9mGTdB1m',
  driveName: 'Dokumente (Shared Documents) der Site rwgintranet',
  eingangPfad: '/IMPORTER/CONTRACT',
  ablageOrdner: 'DONE',
  fehlerOrdner: 'FEHLER',
  maxVersuche: 3,
  excelName: 'Vertragsuebersicht.xlsx',
  maxJeLauf: 10,
  nurDatei: '',
  ocrModell: 'mistral-ocr-latest',
  extraktionsModell: 'mistral-medium-latest'
};

const basis = 'https://graph.microsoft.com/v1.0/drives/' + steuerung.driveId;

steuerung.basis = basis;
steuerung.urlEingang = basis + '/root:' + steuerung.eingangPfad + ':/children?$top=500';
steuerung.urlOrdnerAnlegen = basis + '/root:' + steuerung.eingangPfad + ':/children';
steuerung.urlExcel = basis + '/root:' + steuerung.eingangPfad + '/' + steuerung.excelName + ':/content';

return [{ json: { _steuerung: steuerung } }];

const s = $('Steuerung').first().json._steuerung;
const kinder = $('Eingang lesen').first().json.value || [];
const angelegt = $input.first().json;

const ablage = kinder.find(k => k.folder && k.name === s.ablageOrdner);

// Der Fehlerordner wird vor der Schleife angelegt. Gab es ihn schon,
// antwortet Graph mit einem Konflikt statt mit einer Kennung - dann
// steht er in der Auflistung des Eingangs.
const fehlerAusListe = kinder.find(k => k.folder && k.name === s.fehlerOrdner);
const fehlerOrdnerId = (angelegt && angelegt.id) ? angelegt.id : (fehlerAusListe ? fehlerAusListe.id : null);

const dateien = kinder
  .filter(k => k.file && /\.pdf$/i.test(k.name))
  .filter(k => !s.nurDatei || k.name.indexOf(s.nurDatei) !== -1)
  .slice(0, s.maxJeLauf);

return dateien.map(d => ({
  json: {
    item_id: d.id,
    datei_name: d.name,
    bytes_sharepoint: d.size,
    sharepoint_url: d.webUrl,
    sharepoint_pfad: s.eingangPfad + '/' + d.name,
    ablage_ordner_id: ablage ? ablage.id : null,
    ablage_pfad: s.eingangPfad + '/' + s.ablageOrdner,
    fehler_ordner_id: fehlerOrdnerId,
    fehler_pfad: s.eingangPfad + '/' + s.fehlerOrdner,
    url_inhalt: s.basis + '/items/' + d.id + '/content',
    url_verschieben: s.basis + '/items/' + d.id
  }
}));

const crypto = require('crypto');

const kopf = $('Je Datei').first().json;
const puffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const hash = crypto.createHash('sha256').update(puffer).digest('hex');

return [{
  json: Object.assign({}, kopf, { datei_hash: hash, bytes: puffer.length }),
  binary: $input.first().binary
}];

const quelle = $('Hash bilden').first();
const stand = $input.first().json;

return [{
  json: Object.assign({}, quelle.json, {
    id: stand.id,
    status_vorher: stand.status,
    hat_ocr: stand.hat_ocr === true,
    versuche: stand.versuche || 0
  }),
  binary: quelle.binary
}];

const kopf = $('Zeile sichern').first().json;
const s = $('Steuerung').first().json._steuerung;
const antwort = $input.first().json;

const seiten = Array.isArray(antwort.pages) ? antwort.pages : [];

const text = seiten
  .map(seite => seite.markdown || seite.text || seite.content || '')
  .filter(Boolean)
  .join('\n\n--- SEITENWECHSEL ---\n\n');

const woerter = text ? text.split(/\s+/).filter(Boolean).length : 0;

return [{
  json: {
    id: kopf.id,
    ocr_text: text,
    seiten: seiten.length,
    woerter: woerter,
    ocr_modell: s.ocrModell
  }
}];

const s = $('Steuerung').first().json._steuerung;
const quelle = $input.first().json;
const text = quelle.ocr_text || '';

function normalisieren(wert) {
  return String(wert || '')
    .replace(/&amp;/g, '&')
    .replace(/\r/g, '')
    .replace(/[ \t]+/g, ' ')
    .trim();
}

// Die drei internen Gesellschaften der RWG. Steht eine davon auf der
// Kundenseite des Vertrags, ist sie der Mandant und niemals der
// Vertragspartner. Die Voraberkennung ist nur ein Hinweis an das
// Modell, keine Vorgabe.
const gesellschaften = [
  { name: 'RWG Rheinland eG', muster: 'RWG Rheinland eG' },
  { name: 'Obst und Gemüse GmbH', muster: 'Obst und Gemüse GmbH|O&G|Obst\\s*&\\s*Gemüse' },
  { name: 'Baumarkt GmbH', muster: 'Baumarkt GmbH' }
];

const kundenfelder = ['Kunde', 'Leasingnehmer', 'Besteller', 'Antragsteller'];

function mandantErkennen(rohtext) {
  const t = normalisieren(rohtext);
  for (const g of gesellschaften) {
    for (const feld of kundenfelder) {
      const regel = new RegExp(feld + '[\\s\\S]{0,250}?(' + g.muster + ')', 'i');
      if (regel.test(t)) return g.name;
    }
  }
  return null;
}

const mandantErkannt = mandantErkennen(text);

const felder = [
  'Definition', 'Mandant', 'Vertragsart', 'Vertragspartner',
  'Lieferantennummer', 'Vertragsnummer', 'Laufzeit Beginn', 'Laufzeit Ende',
  'Intervalle', 'Verlängerung', 'Kündigungsfrist', 'Kündigung zum',
  'Preis Netto', 'Preis Brutto', 'Kosten Jährlich', 'Sparte/Bereich',
  'Standortinfo', 'Kostenstelle'
];

const vorlage = '{\n' + felder.map(f => '  "' + f + '": null').join(',\n') + '\n}';

const systemtext = [
  'Du extrahierst Vertragsdaten aus OCR-Texten.',
  'Antworte ausschließlich als valides JSON.',
  'Wenn ein Wert nicht eindeutig vorhanden ist, setze ihn auf null.',
  'Erfinde nichts.',
  'Alle folgenden Felder sind Pflichtfelder der Extraktion und müssen aktiv gesucht werden: ' + felder.join(', ') + '.',
  'Wichtige Fachregeln:',
  '"Mandant" ist immer die interne Gesellschaft bzw. der interne Kunde auf RWG-Seite.',
  '"Vertragspartner" ist immer die externe Gegenseite des Vertrags.',
  'Wenn im Dokument ein Abschnitt wie "Kunde", "Antragsteller", "Leasingnehmer", "Besteller" oder "Name" auf der Kundenseite genannt wird, dann ist dies in der Regel der Mandant.',
  'Wenn im Dokument eine externe Partei als "Leasinggeber", "Vermieter", "Dienstleister", "Anbieter", "Versicherer", "Lieferant", "Verkäufer" oder "Auftragnehmer" bezeichnet wird, dann ist dies in der Regel der Vertragspartner.',
  'Spezielle Regeln für Mandant:',
  'Steht bei "Kunde" oder vergleichbaren Kundenfeldern "RWG Rheinland eG", dann ist Mandant = "RWG Rheinland eG".',
  'Steht dort "Obst und Gemüse GmbH", "O&G" oder eine ähnliche Schreibweise, dann ist Mandant = "Obst und Gemüse GmbH".',
  'Steht dort "Baumarkt GmbH" oder eine ähnliche Schreibweise, dann ist Mandant = "Baumarkt GmbH".',
  'Interne Gesellschaften wie RWG Rheinland eG, Obst und Gemüse GmbH oder Baumarkt GmbH dürfen nicht als Vertragspartner zurückgegeben werden, sofern sie im Dokument als Kunde, Leasingnehmer oder Besteller auftreten.',
  'In Leasingverträgen ist der Leasinggeber in der Regel der externe Vertragspartner und der Kunde oder Leasingnehmer der Mandant.',
  'Extrahiere Werte möglichst wörtlich aus dem Dokument und fasse nicht zusammen.',
  '"Definition" soll möglichst die konkrete Dokumentbezeichnung oder den Vertragstitel enthalten, nicht eine inhaltliche Beschreibung.',
  '"Vertragsart" soll möglichst den im Dokument genannten Vertragsbegriff enthalten.',
  '"Standortinfo" soll möglichst die vollständige relevante Standortangabe enthalten, nicht nur den Ort.',
  '"Sparte/Bereich" nur dann befüllen, wenn sie im Dokument eindeutig erkennbar ist. Nicht raten.',
  '"Lieferantennummer" muss auch dann extrahiert werden, wenn sie im OCR unter Bezeichnungen wie "Vermittelnder Betriebsr.", "Vermittelnder Betriebsnr.", "Betriebsnr.", "Lieferantennummer" oder ähnlichen Schreibweisen steht.',
  'Werte wie "0183-20450" sind gültige Lieferantennummern und sollen übernommen werden.',
  '"Vertragsnummer" kann auch als "Vertragsnr.", "Vertragsnummer", "Vertrags-Nr." oder ähnlich bezeichnet sein.',
  '"Kostenstelle" kann als "Kostenstelle", "KST", "Kostenst." oder "Kostenträger" bezeichnet sein. Nur übernehmen, wenn das Dokument sie ausdrücklich so benennt. Nicht mit der Vertragsnummer verwechseln.',
  '"Preis Netto" ist der Netto-Betrag ohne Umsatzsteuer.',
  '"Preis Brutto" ist nur zu füllen, wenn ein Bruttopreis explizit angegeben ist.',
  '"Kosten Jährlich" ist nur zu füllen, wenn ein Jahresbetrag explizit genannt ist oder eindeutig berechnet werden kann.',
  '"Laufzeit Beginn" und "Laufzeit Ende" nur füllen, wenn im Dokument etwas dazu steht. Steht dort eine Regel statt eines Datums, etwa "bis auf Widerruf" oder "31.12. des Folgejahres", dann gib genau diesen Wortlaut zurück statt null.',
  '"Intervalle" soll etwa "monatlich", "jährlich" oder "quartalsweise" enthalten, wenn das aus dem Dokument eindeutig hervorgeht.',
  '"Verlängerung", "Kündigungsfrist" und "Kündigung zum" nur übernehmen, wenn explizit genannt.'
].join(' ');

const benutzertext = [
  'Extrahiere aus dem folgenden Vertragstext exakt diese Felder und gib ausschließlich JSON zurück. Verwende genau diese Schlüssel:',
  '',
  vorlage,
  '',
  'Diese Felder müssen alle aktiv gesucht werden:',
  felder.map(f => '- ' + f).join('\n'),
  '',
  'Extraktionsregeln:',
  '- "Mandant" = interne Gesellschaft, Kunde, Antragsteller oder Leasingnehmer auf RWG-Seite.',
  '- "Vertragspartner" = externe Gegenseite.',
  '- Steht im Text ein Abschnitt "Kunde" oder "Name" direkt unter dem Kundenblock, hat dieser Wert für Mandant Vorrang.',
  '- Bei Leasingdokumenten ist der Leasinggeber typischerweise der Vertragspartner.',
  '- Gib keine interne Gesellschaft als Vertragspartner zurück, wenn sie als Kunde oder Leasingnehmer genannt ist.',
  '- Extrahiere Werte möglichst wörtlich und fasse nicht zusammen.',
  '- "Definition" ist die Dokumentbezeichnung oder der Vertragstitel, keine inhaltliche Beschreibung.',
  '- "Sparte/Bereich" nur befüllen, wenn eindeutig erkennbar. Nicht raten.',
  '- "Lieferantennummer" steht oft unter "Vermittelnder Betriebsr.", "Betriebsnr." oder ähnlich; eine Nummer wie "0183-20450" ist zu übernehmen.',
  '- "Kostenstelle" nur übernehmen, wenn das Dokument sie ausdrücklich so benennt.',
  '- "Preis Brutto" und "Kosten Jährlich" nur füllen, wenn explizit genannt oder eindeutig berechenbar.',
  '- Bei Laufzeit- und Kündigungsangaben ohne konkretes Datum den Wortlaut zurückgeben, nicht null.',
  '- Vorab erkannter Mandant: ' + (mandantErkannt || 'null'),
  '- Passt die Voraberkennung plausibel zum OCR-Text, übernimm sie für Mandant.',
  '',
  'Vertragstext:',
  '',
  text
].join('\n');

const anfrage = {
  model: s.extraktionsModell,
  temperature: 0,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: systemtext },
    { role: 'user', content: benutzertext }
  ]
};

return [{
  json: {
    id: quelle.id,
    mandant_erkannt: mandantErkannt,
    anfrage: JSON.stringify(anfrage)
  }
}];

const auftrag = $('Extraktionsauftrag').first().json;
const s = $('Steuerung').first().json._steuerung;
const antwort = $input.first().json;

const nachricht = (((antwort.choices || [])[0] || {}).message || {});

let roh = {};
try {
  roh = JSON.parse(nachricht.content || '{}');
} catch (e) {
  roh = {};
}

// Klartext: was im Vertrag steht. Leerstring und die Zeichenkette
// "null" gelten als nicht gefunden.
function txt(wert) {
  if (wert === null || wert === undefined) return null;
  const v = String(wert).trim();
  if (v === '' || v.toLowerCase() === 'null') return null;
  return v;
}

// Ausgewertet: nur wo eindeutig. Ein Vertrag "bis auf Widerruf"
// behaelt seinen Wortlaut in der Textspalte und bleibt hier null.
function datum(wert) {
  const v = txt(wert);
  if (!v) return null;
  let t = v.match(/(\d{4})-(\d{2})-(\d{2})/);
  if (t) {
    return t[1] + '-' + t[2] + '-' + t[3];
  }
  t = v.match(/(\d{1,2})\s*[.\/-]\s*(\d{1,2})\s*[.\/-]\s*(\d{4})/);
  if (t) {
    const tag = t[1].length === 1 ? '0' + t[1] : t[1];
    const monat = t[2].length === 1 ? '0' + t[2] : t[2];
    return t[3] + '-' + monat + '-' + tag;
  }
  return null;
}

function zahl(wert) {
  const v = txt(wert);
  if (!v) return null;
  const t = v.match(/-?\d[\d.,\s]*\d|-?\d/);
  if (!t) return null;
  let z = t[0].replace(/\s/g, '');
  if (z.indexOf(',') !== -1) {
    z = z.replace(/\./g, '').replace(',', '.');
  } else if (/\.\d{3}(\.|$)/.test(z)) {
    z = z.replace(/\./g, '');
  }
  const n = Number(z);
  return Number.isFinite(n) ? n : null;
}

const daten = {
  id: auftrag.id,
  definition: txt(roh['Definition']),
  mandant: txt(roh['Mandant']),
  vertragsart: txt(roh['Vertragsart']),
  vertragspartner: txt(roh['Vertragspartner']),
  lieferantennummer: txt(roh['Lieferantennummer']),
  vertragsnummer: txt(roh['Vertragsnummer']),
  laufzeit_beginn_text: txt(roh['Laufzeit Beginn']),
  laufzeit_ende_text: txt(roh['Laufzeit Ende']),
  intervalle: txt(roh['Intervalle']),
  verlaengerung: txt(roh['Verlängerung']),
  kuendigungsfrist: txt(roh['Kündigungsfrist']),
  kuendigung_zum_text: txt(roh['Kündigung zum']),
  preis_netto_text: txt(roh['Preis Netto']),
  preis_brutto_text: txt(roh['Preis Brutto']),
  kosten_jaehrlich_text: txt(roh['Kosten Jährlich']),
  sparte_bereich: txt(roh['Sparte/Bereich']),
  standortinfo: txt(roh['Standortinfo']),
  kostenstelle: txt(roh['Kostenstelle']),
  laufzeit_beginn: datum(roh['Laufzeit Beginn']),
  laufzeit_ende: datum(roh['Laufzeit Ende']),
  kuendigung_zum: datum(roh['Kündigung zum']),
  preis_netto: zahl(roh['Preis Netto']),
  preis_brutto: zahl(roh['Preis Brutto']),
  kosten_jaehrlich: zahl(roh['Kosten Jährlich']),
  rohdaten: roh,
  extraktions_modell: s.extraktionsModell
};

const gefuellt = Object.keys(daten).filter(k => {
  if (k === 'id' || k === 'rohdaten' || k === 'extraktions_modell') return false;
  return daten[k] !== null;
});

return [{
  json: {
    id: auftrag.id,
    daten: daten,
    felder_gefuellt: gefuellt.length,
    felder_liste: gefuellt
  }
}];
